import{z as o,x as s,o as B,c as C,q as r,j as n,D as A,d as e,s as i,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"税负敏感的组合","description":"","frontmatter":{"title":"税负敏感的组合","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pf-tax-aware.md","filePath":"quant/pf-tax-aware.md","lastUpdated":1791063341000}'),d={name:"quant/pf-tax-aware.md"};function p(D,E,m,F,u,f){const t=s("Mermaid");return B(),C("div",null,[E[2]||(E[2]=r('<h1 id="税负敏感的组合" tabindex="-1">税负敏感的组合 <a class="header-anchor" href="#税负敏感的组合" aria-label="Permalink to &quot;税负敏感的组合&quot;">​</a></h1><div class="epigraph"><p>税基是一个状态变量：它不随价格走，随你每一次实现行为走；忽略它的优化器，在一个看不见的维度上负债。</p><footer>—— 据 Constantinides, Capital Market Equilibrium with Personal Taxes, Econometrica, 1983 整理</footer></div><p><a href="/quant/pf-rebalancing">上一课</a>把再平衡当政策：触发、带宽、成本核，凸性的价格算了账。缺口是成本核里最重的一笔在费率表上查不到：税。已有<a href="/quant/tax-aware-portfolio">税务感知组合</a>与<a href="/quant/tax-deferred">税率与递延税</a>写了机制与账户框架；本课把税写进组合构建的目标函数与状态空间——不是报税操作，是构建层的税后优化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>税把收益拆成两本账：市场收益与税后收益，两者的排序可以不同。错法一：用税前夏普选策略——高换手的动量策略税前年化亮眼，短持有期全额按短期税率实现，税后可能输给低换手的价值组合；错法二：把损失收获当免费加项——它是嵌入的税收择时期权（Constantinides 1983：价格路径波动时随时把浮亏变现、重置税基），但受洗售规则、涨回风险与可收获亏损存量的限制；错法三：把再平衡与税分开设计——上一课对称的成本核在税后世界不再对称：卖出盈利比卖出亏损贵，无交易区必须变形。</p><p><span class="marginnote">洗售规则（wash sale）就是税法给损失收获设的闸门：卖出亏损资产后 30 天内（美国口径）买回同一或实质相同的资产，刚收获的亏损不得抵税。这解释了为什么收获损失要配一个「高相关但不同」的替代持仓——替代品正是绕开这扇闸门的桥。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法上，本课把税从成本核的脚注升格为问题的结构：目标函数、状态空间与可用技术清单三处各改一处，改完的仍是一个每期可解、可验收的组合构建问题。顺序固定：先定税后目标，再增广状态，最后才接技术清单——顺序颠倒，损失收获会退化成事后的择时故事。验收沿用前几课的口径：优化器输出的每一笔实现行为，都要能在税后账本里指认动机。</p><h3 id="目标函数与状态增广" tabindex="-1">目标函数与状态增广 <a class="header-anchor" href="#目标函数与状态增广" aria-label="Permalink to &quot;目标函数与状态增广&quot;">​</a></h3><p>第一步改目标：最大化期望税后终值，税率按持有期分段，于是持有期本身成为优化变量——跨过长短期分界线的每一笔持仓都背着一个等待价值。第二步增广状态：记 \\((w,b)\\)，\\(w\\) 是持仓向量，\\(b\\) 是对应的税基向量；决策的最小单位从「名字」细化到「批次」（lot），高成本基础的批次先卖（特定批次识别），实现利得的时点与规模成为显式选择。第三步把技术清单接进优化器：损失收获与因子暴露维持并行——卖出亏损名字的同时用高相关替代维持暴露，等待洗售窗口过期；再平衡优先用分红与外部流入完成，卖单只补差额；资产位置把高换手、高税率的收益源放进递延账户，低换手的放进应税账户（<a href="/quant/tax-deferred">税率与递延税</a>的框架在此接入）。</p>',10)),(B(),n(l,null,{default:A(()=>[i(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20STATE%5B%22%E7%8A%B6%E6%80%81%EF%BC%9A%E6%8C%81%E4%BB%93%20w%20%E4%B8%8E%E7%A8%8E%E5%9F%BA%20b%22%5D%20--%3E%20DEC%5B%22%E5%86%B3%E7%AD%96%EF%BC%9A%E5%8D%96%E7%9B%88%E5%88%A9%E6%89%B9%E6%AC%A1%E6%88%96%E5%8D%96%E4%BA%8F%E6%8D%9F%E6%89%B9%E6%AC%A1%E6%88%96%E6%8C%81%E6%9C%89%22%5D%0A%20%20DEC%20--%3E%7C%E5%8D%96%E7%9B%88%E5%88%A9%7C%20TAX%5B%22%E5%AE%9E%E7%8E%B0%E5%88%A9%E5%BE%97%EF%BC%9A%E6%8C%89%E6%8C%81%E6%9C%89%E6%9C%9F%E8%AE%A1%E7%A8%8E%22%5D%0A%20%20DEC%20--%3E%7C%E5%8D%96%E4%BA%8F%E6%8D%9F%7C%20HARVEST%5B%22%E6%94%B6%E8%8E%B7%E6%8D%9F%E5%A4%B1%EF%BC%9A%E9%87%8D%E7%BD%AE%E7%A8%8E%E5%9F%BA%22%5D%0A%20%20HARVEST%20--%3E%20REPL%5B%22%E6%9B%BF%E4%BB%A3%E6%8C%81%E4%BB%93%EF%BC%9A%E7%BB%B4%E6%8C%81%E5%9B%A0%E5%AD%90%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20TAX%20--%3E%20UPDATE%5B%22%E7%A8%8E%E5%90%8E%E8%B4%A2%E5%AF%8C%E4%B8%8E%E7%A8%8E%E5%9F%BA%E6%9B%B4%E6%96%B0%22%5D%0A%20%20REPL%20--%3E%20UPDATE%0A%20%20UPDATE%20--%3E%20OPT%5B%22%E4%B8%8B%E4%B8%80%E6%9C%9F%E7%A8%8E%E5%90%8E%E4%BC%98%E5%8C%96%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"批次识别的数字实例：同一只股票，去年 40 元买过 100 股，上月 60 元又买 100 股，今天 70 元要减仓 100 股。卖哪一批？卖 40 元批次实现利得 3000 元，卖 60 元批次只实现 1000 元——同样的卖单，当年税单差三倍，「先卖哪批」由此成为显式决策。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"损失收获为什么像期权：同一只股票，涨回与跌深都创造行动机会——跌了收获税盾，涨了持有递延；波动越大、税律越宽，这组嵌近期权越值钱。这正是 Constantinides 把个人税收写进均衡的洞见：理性的实现行为本身就是收益来源。代价三项：收获当期的跟踪偏离、洗售窗口内的暴露缺口、以及存量约束——组合里可收获的亏损是有限的，年景好时这项 alpha 自然枯竭，报告时要把「当年收获额」与其可得性分开写。无交易区为什么不对称：把同样的偏离纠正回来，往盈利方向减仓要付资本利得税，往亏损方向减仓反而收获税盾，最优带的中心向「保留盈利」一侧偏移——上一课对称的 \\(\\kappa\\) 在这里分裂成两个数。度量的最后一块是税后归因：把当年实现行为产生的税负单列一条，与市场层面的税（如基金强制分红再投资）分开，否则税后业绩的波动没人能解释。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"量级感受：以美国口径，短期税率与长期税率的差可达约二十个百分点；一笔正盈利的持仓跨越长短期分界线后再卖，省下的税可达仓位本身的数个百分点——持期是优化变量，不是会计事实。")],-1)),(B(),n(l,null,{default:A(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20DRIFT%5B%22%E6%8C%81%E4%BB%93%E5%81%8F%E7%A6%BB%E7%9B%AE%E6%A0%87%EF%BC%9A%E9%9C%80%E8%A6%81%E5%86%8D%E5%B9%B3%E8%A1%A1%22%5D%20--%3E%20Q%7B%22%E5%81%8F%E7%A6%BB%E6%9D%A5%E8%87%AA%E5%93%AA%E4%B8%80%E4%BE%A7%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E7%9B%88%E5%88%A9%E8%B6%85%E6%A0%87%22%7C%20SELLW%5B%22%E5%8D%96%E7%9B%88%E5%88%A9%E6%89%B9%E6%AC%A1%EF%BC%9A%E7%BC%B4%E8%B5%84%E6%9C%AC%E5%88%A9%E5%BE%97%E7%A8%8E%22%5D%0A%20%20Q%20--%3E%7C%22%E4%BA%8F%E6%8D%9F%E8%B6%85%E6%A0%87%22%7C%20SELLL%5B%22%E5%8D%96%E4%BA%8F%E6%8D%9F%E6%89%B9%E6%AC%A1%EF%BC%9A%E6%94%B6%E8%8E%B7%E7%A8%8E%E7%9B%BE%22%5D%0A%20%20SELLW%20--%3E%20SLOW%5B%22%E7%BA%A0%E6%AD%A3%E6%88%90%E6%9C%AC%E9%AB%98%EF%BC%9A%E5%B8%A6%E5%AE%BD%E5%90%91%E7%9B%88%E5%88%A9%E4%BE%A7%E5%8F%98%E5%AE%BD%22%5D%0A%20%20SELLL%20--%3E%20CHEAP%5B%22%E7%BA%A0%E6%AD%A3%E6%9C%89%E8%A1%A5%E8%B4%B4%EF%BC%9A%E9%85%8D%E6%9B%BF%E4%BB%A3%E6%8C%81%E4%BB%93%E7%BB%B4%E6%8C%81%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20SLOW%20--%3E%20NT%5B%22%E6%97%A0%E4%BA%A4%E6%98%93%E5%8C%BA%E4%B8%8D%E5%AF%B9%E7%A7%B0%EF%BC%9A%E4%B8%AD%E5%BF%83%E5%81%8F%E5%90%91%E4%BF%9D%E7%95%99%E7%9B%88%E5%88%A9%22%5D%0A%20%20CHEAP%20--%3E%20NT%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写各国税法细则与申报操作（框架见<a href="/quant/tax-aware-portfolio">税务感知组合</a>），不做税务建议；递延账户内部的构建回到前几课的一般形式。税收 alpha 的可扩展性受亏损存量与替代工具相关性约束，不是常数收益来源；把损失收获回测成每年固定加点，等于把期权价值当票息。再平衡带宽的税后修正与上一课共用一套政策语言，但参数要重估。</p><p><span class="marginnote">常见误区：初学者容易把税负敏感组合理解成报税季的会计操作，实际上它改变的是下单前的每一次选择——卖哪一批、何时卖、把哪个策略放进哪个账户。省税发生在交易执行之前，报税只是把结果记录下来。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>税后优化的两个改造：目标换成税后终值，状态增广为（持仓、税基、批次）。</li><li>损失收获是嵌近期权，价值随波动与税律宽度上升，受洗售、跟踪偏离与存量约束。</li><li>税让成本核不对称：无交易区向保留盈利一侧偏移，再平衡参数须按税后重估。</li><li>资产位置与批次识别是零成本的构建层决策，先于任何复杂优化。</li><li>出处：Constantinides, <em>Econometrica</em>, 1983；Constantinides, <em>JF</em>, 1984（最优实现时机）；框架据 tax-aware 两课整理。</li></ul>',5))])}const c=o(d,[["render",p]]);export{T as __pageData,c as default};
